            block.homeTeam = homeTeamName;
            block.home_firstGoal_lastGoal = TemplateChoice.MatchFirstGoal;
            block.awayTeam = awayTeamName;
            block.away_firstGoal_lastGoal = TemplateChoice.MatchLastGoal;
            block.Visible = true;

